from fastapi import APIRouter

from app import schemas
from app.services import classify

router = APIRouter()


@router.post("/orders", response_model=schemas.OrderOut)
def create_order(payload: schemas.OrderIn):
    tier, fee = classify(payload.items, payload.priority)
    return {"items": payload.items, "tier": tier, "fee": fee}

