from fastapi.testclient import TestClient

from app.main import app

client = TestClient(app)


def post(items, priority=False):
    return client.post("/orders", json={"items": items, "priority": priority})


def test_standard():
    r = post(3)
    assert r.status_code == 200
    assert r.json() == {"items": 3, "tier": "standard", "fee": 10}


def test_bulk_threshold():
    r = post(10)
    assert r.json()["tier"] == "bulk"
    assert r.json()["fee"] == 5


def test_priority_is_express():
    r = post(2, priority=True)
    assert r.json()["tier"] == "express"
    assert r.json()["fee"] == 20


def test_priority_beats_bulk():
    r = post(50, priority=True)
    assert r.json()["tier"] == "express"
